from collections import deque,Counter

def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   v=g[r][c]
   if (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   for rr,cc in q:
    cells.append((rr,cc))
    for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
     if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and g[nr][nc]==v:
      seen.add((nr,nc)); q.append((nr,nc))
   rs=[x for x,y in cells]; cs=[y for x,y in cells]
   out.append(dict(color=v,cells=cells,n=len(cells),box=(min(rs),min(cs),max(rs),max(cs))))
 return out
